function ensureQuickPlaces(){const search=document.querySelector('.searchbox'),row=search?.querySelector('.row');if(!search||!row)return null;let quick=$('searchQuickPlaces');if(!quick){quick=document.createElement('div');quick.id='searchQuickPlaces';quick.className='search-quick-places';quick.innerHTML='<button id="quickHomeBtn" class="quick-place" aria-label="Navigovať domov"><span class="quick-place-icon" aria-hidden="true"><svg viewBox="0 0 24 24"><path d="M3 11.5 12 4l9 7.5"/><path d="M5.5 10.5V20h13v-9.5"/><path d="M9.5 20v-6h5v6"/></svg></span><span>Domov</span></button><button id="quickWorkBtn" class="quick-place" aria-label="Navigovať do práce"><span class="quick-place-icon" aria-hidden="true"><svg viewBox="0 0 24 24"><rect x="3" y="7" width="18" height="13" rx="2"/><path d="M8 7V5.5A1.5 1.5 0 0 1 9.5 4h5A1.5 1.5 0 0 1 16 5.5V7M3 12h18M10 12v2h4v-2"/></svg></span><span>Práca</span></button>';row.insertAdjacentElement('afterend',quick)}return quick}
function useQuickPlace(place,label){if(place){selectDestination(place);return}const status=$('searchStatus');if(status)status.textContent=`${label} ešte nie je nastavený. Vyhľadajte adresu a uložte ju v nastaveniach.`}
