async function initMap(){const L=window.L;state.L=L;state.map=L.map('map',{zoomControl:true,attributionControl:true,rotate:true,bearing:0,rotateControl:false,dragRotate:false,touchRotate:false,shiftKeyRotate:false}).setView([48.9984,21.2393],12);L.tileLayer('https://www.waze.com/row-tiles/live/base/{z}/{x}/{y}/tile.png',{maxZoom:20,attribution:'Waze'}).addTo(state.map);startGPS();setInterval(loadAlerts,30000);setTimeout(loadAlerts,2200)}
