// Pairing
const PAIR_API='https://dimvegkezslqjtsxdohp.supabase.co/functions/v1/twpair';
let pairPollTimer=null;
function stopPairPolling(){if(pairPollTimer){clearInterval(pairPollTimer);pairPollTimer=null}}
async function pairing(action,payload={}){const r=await fetch(PAIR_API,{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({action,...payload}),cache:'no-store'}),d=await r.json().catch(()=>({}));if(!r.ok)throw new Error(d.error||'pairing');return d}
async function beginNewPair(body){
  stopPairPolling();body.innerHTML='<p>Pripravujem bezpečné prepojenie…</p>';
  const d=await pairing('start');
  const dev={version:2,deviceId:d.deviceId,deviceSecret:d.deviceSecret,paired:false};save(LS.device,dev);
  body.innerHTML=`${d.qrDataUrl?`<img src="${esc(d.qrDataUrl)}" alt="QR kód na prepojenie mobilu" style="max-width:260px;width:80%;height:auto">`:''}<div class="code">${esc(d.pairingCode||'')}</div><p><b>Naskenujte QR kód iPhonom.</b><br>Po potvrdení sa spojenie na tejto obrazovke aktivuje automaticky.</p><p id="pairStatus">Čakám na mobil…</p>`;
  const expires=Date.parse(d.expiresAt||'')||Date.now()+10*60*1000;
  const check=async()=>{try{const st=await pairing('status',dev);if(st.paired){stopPairPolling();const saved={...dev,paired:true,claimedAt:st.claimedAt||new Date().toISOString()};save(LS.device,saved);body.innerHTML='<div style="font-size:46px">✅</div><h3>Mobil je prepojený</h3><p>Prepojenie bolo úspešne potvrdené.</p><button id="pairAgain" class="btn">Spárovať iný mobil</button>';const a=$('pairAgain');if(a)a.onclick=()=>beginNewPair(body);try{renderTeslaSettings()}catch{};return}if(st.status==='expired'||Date.now()>expires){stopPairPolling();body.innerHTML='<p>Párovací kód vypršal.</p><button id="pairAgain" class="btn">Vytvoriť nový kód</button>';const a=$('pairAgain');if(a)a.onclick=()=>beginNewPair(body)}}catch{}};
  pairPollTimer=setInterval(check,1800);setTimeout(check,350);
}
async function startPair(){const body=$('pairBody');$('pairModal').classList.remove('hidden');stopPairPolling();try{const credentials=load(LS.device,null);if(credentials?.deviceId&&credentials?.deviceSecret){try{const st=await pairing('status',credentials);if(st.paired){const saved={...credentials,paired:true,claimedAt:st.claimedAt||credentials.claimedAt};save(LS.device,saved);body.innerHTML='<div style="font-size:46px">✅</div><h3>Mobil je prepojený</h3><p>Spojenie je aktívne.</p><button id="pairAgain" class="btn">Spárovať iný mobil</button>';const a=$('pairAgain');if(a)a.onclick=()=>beginNewPair(body);return}}catch{}}await beginNewPair(body)}catch(e){body.innerHTML=`<p>${esc(e.message)}</p><button id="pairAgain" class="btn">Skúsiť znova</button>`;const a=$('pairAgain');if(a)a.onclick=()=>beginNewPair(body)}}

// Smart Music window
const MUSIC_WIN_KEY='teslaWaze:musicWindow:v1';
function musicWindowState(){return load(MUSIC_WIN_KEY,{width:520,height:Math.min(window.innerHeight,760),minimized:false})}
function applyMusicWindow(){const shell=document.querySelector('.music-shell');if(!shell)return;const cfg=musicWindowState(),maxW=Math.max(340,Math.min(window.innerWidth-20,760)),maxH=Math.max(180,window.innerHeight-20);shell.style.width=`${Math.max(340,Math.min(maxW,cfg.width||520))}px`;shell.style.height=cfg.minimized?'154px':`${Math.max(360,Math.min(maxH,cfg.height||Math.min(window.innerHeight,760)))}px`;shell.classList.toggle('music-minimized',!!cfg.minimized);const b=$('musicMinimize');if(b)b.textContent=cfg.minimized?'Rozbaliť':'Minimalizovať'}
function saveMusicWindow(patch){const cfg={...musicWindowState(),...patch};save(MUSIC_WIN_KEY,cfg);applyMusicWindow()}
function ensureMusicWindowControls(){
  const shell=document.querySelector('.music-shell'),head=document.querySelector('.music-head');if(!shell||!head||$('musicMinimize'))return;
  const min=document.createElement('button');min.id='musicMinimize';min.className='btn music-min-btn';min.textContent='Minimalizovať';head.insertBefore(min,$('closeMusic'));
  const left=document.createElement('div');left.className='music-resize music-resize-left';left.setAttribute('aria-hidden','true');shell.appendChild(left);
  const top=document.createElement('div');top.className='music-resize music-resize-top';top.setAttribute('aria-hidden','true');shell.appendChild(top);
  min.onclick=()=>saveMusicWindow({minimized:!musicWindowState().minimized});
  const bindResize=(node,mode)=>node.addEventListener('pointerdown',e=>{e.preventDefault();node.setPointerCapture?.(e.pointerId);const cfg=musicWindowState(),sx=e.clientX,sy=e.clientY,sw=shell.getBoundingClientRect().width,sh=shell.getBoundingClientRect().height;const move=ev=>{if(mode==='w'){const w=Math.max(340,Math.min(Math.min(window.innerWidth-20,760),sw+(sx-ev.clientX)));shell.style.width=w+'px'}else{const h=Math.max(360,Math.min(window.innerHeight-20,sh+(sy-ev.clientY)));shell.style.height=h+'px'}};const up=ev=>{node.releasePointerCapture?.(ev.pointerId);node.removeEventListener('pointermove',move);node.removeEventListener('pointerup',up);node.removeEventListener('pointercancel',up);saveMusicWindow({width:Math.round(shell.getBoundingClientRect().width),height:Math.round(shell.getBoundingClientRect().height),minimized:false})};node.addEventListener('pointermove',move);node.addEventListener('pointerup',up);node.addEventListener('pointercancel',up)});
  bindResize(left,'w');bindResize(top,'h');applyMusicWindow();window.addEventListener('resize',applyMusicWindow);
}
function syncMusicFab(){const f=$('musicFab'),m=$('musicModal');if(!f||!m)return;f.style.display=m.classList.contains('hidden')?'flex':'none'}
function setMusicWindowOpen(on){const m=$('musicModal');if(!m)return;m.classList.toggle('hidden',!on);syncMusicFab()}
