function renderMusicStatus(){const n=Object.keys(music.profile.tracks).length,y=music.profile.youtube;$('musicStatus').textContent=`${n} naučených skladieb`;$('musicAccount').textContent=y.connected?`${y.email||'lukaslejko@gmail.com'} · synchronizované`:'lukaslejko@gmail.com · YouTube nepripojený';$('musicMiniStatus').textContent=$('musicAccount').textContent}
function musicCard(t){const s=mt(t),play=!!t.streamUrl,yt=!!(t.youtubeId||s.youtubeId||String(t.id||'').startsWith('youtube:'));return `<div class="music-track" data-mrow="${esc(s.id)}"><img class="music-art" src="${esc(t.artwork||'')}" onerror="this.style.visibility='hidden'"><div><div class="music-title">${esc(t.title||'Bez názvu')}</div><div class="music-sub">${esc(t.artist||'')} · ${esc(t.source||'')}</div><span class="music-source">${play?'▶ FREE':yt?'▶ YOUTUBE':esc((t.source||'NÁJSŤ').toUpperCase())}</span>${s.liked?' <span class="music-source">♥</span>':''}</div><button class="btn ${play||yt?'primary':''}" data-mplay="${esc(s.id)}">${play||yt?'Prehrať':'Zdroje'}</button></div>`}
function renderMusicList(a=musicItems(),node=$('musicList')){node.innerHTML=a.length?a.map(musicCard).join(''):'<div class="music-empty">Zatiaľ nič. Synchronizuj YouTube alebo vyhľadaj skladbu.</div>';const open=t=>{if(!t)return;if(t.streamUrl||t.youtubeId||String(t.id||'').startsWith('youtube:'))mplay(t);else musicSources(t)};node.querySelectorAll('[data-mplay]').forEach(b=>b.onclick=e=>{e.stopPropagation();open(a.find(x=>mt(x).id===b.dataset.mplay))});node.querySelectorAll('[data-mrow]').forEach(r=>r.onclick=()=>open(a.find(x=>mt(x).id===r.dataset.mrow)))}
function renderPlayer(){const r=$('musicPlayer');if(!music.current){r.innerHTML='<div class="music-empty">Vyber skladbu.</div>';music.audio=null;music.ytPlayer=null;return}const s=mt(music.current),yt=music.current.youtubeId||s.youtubeId||(String(music.current.id||'').startsWith('youtube:')?String(music.current.id).slice(8):'');const media=yt?`<div id="ytPlayerHost" class="yt-player"></div>`:'<audio controls></audio>';r.innerHTML=`<div class="music-now"><img class="music-art" src="${esc(music.current.artwork||'')}"><div><div class="music-title">${esc(music.current.title)}</div><div class="music-sub">${esc(music.current.artist||'')} · ${esc(music.current.source||'')}</div></div></div>${media}<div class="music-controls music-controls-6"><button class="btn" data-ma="prev">⏮</button>${yt?'': '<button class="btn primary" data-ma="toggle">▶</button>'}<button class="btn" data-ma="next">⏭</button><button class="btn ${music.shuffle?'primary':''}" data-ma="shuffle">🔀</button><button class="btn ${music.autoNext?'primary':''}" data-ma="auto">Auto ▶</button><button class="btn ${s.liked?'primary':''}" data-ma="like">♥</button></div>`;music.audio=r.querySelector('audio');music.ytPlayer=null;if(music.audio){music.audio.src=music.current.streamUrl||'';wireAudio();const tb=r.querySelector('[data-ma=toggle]');if(tb)tb.onclick=()=>music.audio.paused?music.audio.play():music.audio.pause()}else if(yt){setupYoutubePlayer(yt)}r.querySelector('[data-ma=prev]').onclick=mprev;r.querySelector('[data-ma=next]').onclick=mnext;r.querySelector('[data-ma=shuffle]').onclick=()=>{music.shuffle=!music.shuffle;save('teslaWaze:musicShuffle:v1',music.shuffle);renderPlayer()};r.querySelector('[data-ma=auto]').onclick=()=>{music.autoNext=!music.autoNext;save('teslaWaze:musicAutoNext:v1',music.autoNext);renderPlayer()};r.querySelector('[data-ma=like]').onclick=()=>{mev('like',music.current);renderMusicList();renderPlayer()}}
function wireAudio(){if(!music.audio)return;music.audio.onended=()=>{if(music.current)mev('complete',music.current);if(music.autoNext)mnext()};music.audio.onplay=()=>{const b=document.querySelector('[data-ma=toggle]');if(b)b.textContent='⏸'};music.audio.onpause=()=>{const b=document.querySelector('[data-ma=toggle]');if(b)b.textContent='▶'}}
function ensureMusicQueue(){const items=musicItems();if(!music.queue.length||!music.current||!music.queue.some(x=>mt(x).id===mt(music.current).id)){music.queue=items;save(LS.queue,music.queue)}return music.queue}
function mplay(t){const st=mt(t),yt=t.youtubeId||st.youtubeId||(String(t.id||'').startsWith('youtube:')?String(t.id).slice(8):'');if(!t.streamUrl&&!yt)return musicSources(t);if(music.current&&music.started&&Date.now()-music.started<15000)mev('skip',music.current);const replay=music.current&&mt(music.current).id===mt(t).id;music.current=t;renderPlayer();music.started=Date.now();mev(replay?'replay':'play',t);if(music.audio)music.audio.play().catch(()=>{})}
