async function musicSearch(){const q=$('musicSearch').value.trim(),o=$('musicSearchResults');if(!q)return;o.innerHTML='<div class="music-empty">Hľadám legálne free zdroje…</div>';try{const d=await (await fetch('/api/music/resolve?q='+encodeURIComponent(q),{cache:'no-store'})).json(),a=d.results||[];music.queue=a;save(LS.queue,a);renderMusicList(a,o)}catch{o.innerHTML='<div class="music-empty">Vyhľadávanie zdrojov zlyhalo.</div>'}}
async function musicSources(t){const o=$('musicSources'),q=`${t.artist||''} ${t.title||''}`.trim();o.innerHTML='<div class="music-card">Hľadám ďalšie zdroje…</div>';let free=[];try{free=(await (await fetch('/api/music/resolve?q='+encodeURIComponent(q))).json()).results.filter(x=>x.streamUrl)}catch{}o.innerHTML=`<div class="music-card"><b>${esc(t.artist||'')} — ${esc(t.title||'')}</b>${free.length?free.map(musicCard).join(''):'<div class="music-empty">Zodpovedajúca celá free verzia sa nenašla.</div>'}<div class="chips"><button class="chip" data-ext="yt">YouTube Music</button><button class="chip" data-ext="sc">SoundCloud</button><button class="chip" data-ext="bc">Bandcamp</button></div></div>`;o.querySelectorAll('[data-mplay]').forEach(b=>b.onclick=()=>{const x=free.find(y=>mt(y).id===b.dataset.mplay);if(x){music.queue=free;mplay(x)}});o.querySelectorAll('[data-ext]').forEach(b=>b.onclick=()=>{const enc=encodeURIComponent(q),u=b.dataset.ext==='yt'?`https://music.youtube.com/search?q=${enc}`:b.dataset.ext==='sc'?`https://soundcloud.com/search/sounds?q=${enc}`:`https://bandcamp.com/search?q=${enc}`;window.open(u,'_blank')})}
async function syncYoutube(){try{const r=await fetch('/api/music/youtube/likes',{cache:'no-store'});if(r.status===401){const u='https://tesla-waze.vercel.app/api/music/google/start';const hosted=/raw\.githack\.com|webflow\.io/.test(location.hostname);if(hosted){const a=document.createElement('a');a.href=u;a.target='_blank';a.rel='noopener noreferrer';document.body.appendChild(a);a.click();a.remove();if($('musicAccount'))$('musicAccount').textContent='Prihlásenie YouTube otvorené v novom okne';return}location.assign(u);return}if(!r.ok)throw 0;const d=await r.json();(d.items||[]).forEach(t=>{const s=mt(t);s.score=Math.max(s.score,4);s.liked=true;s.artwork=t.artwork||s.artwork;s.source='YouTube Like';ma(t.artist).score=Math.max(ma(t.artist).score,2.5)});music.profile.youtube={connected:true,email:d.email||'lukaslejko@gmail.com',lastSync:new Date().toISOString(),count:d.count||0};save(LS.music,music.profile);music.queue=musicItems();save(LS.queue,music.queue);renderMusicStatus();renderMusicList()}catch{}}

